Rules.InvariantScript:
If(IsBlank(varBookingView), Set(varBookingView, "calendar"));
If(IsBlank(varCalMonth), Set(varCalMonth, Date(Year(Today()), Month(Today()), 1)));
If(IsBlank(varCalDay), Set(varCalDay, Today()))

Set(varCurrentBooking, Blank());
Set(varCurrentAsset, Blank());
Set(varCurrentSetup, Blank());
Navigate(scr_BookingDetail, ScreenTransition.Fade)

With(
    {
        first: DateAdd(
            varCalMonth,
            -(Weekday(varCalMonth, StartOfWeek.Monday) - 1),
            TimeUnit.Days
        )
    },
    ForAll(
        Sequence(42) As s,
        With(
            { d: DateAdd(first, s.Value - 1, TimeUnit.Days) },
            {
                CellDate: d,
                DayNum: Day(d),
                InMonth: Month(d) = Month(varCalMonth),
                Bookings: CountRows(
                    Filter(
                        Equipment_Bookings As bk,
                        bk.StartDate <= d,
                        bk.EndDate >= d,
                        IsBlank(varBookingDevice)
                            || bk.Title = varBookingDevice,
                        IsEmpty(colGroupFilter)
                            || LookUp(Equipment_Assets, Titel = bk.Title).OwnerGroup.Value in colGroupFilter.Value
                            || LookUp(Equipment_Assets, Titel = bk.Title).UserGroup.Value in colGroupFilter.Value
                    )
                )
            }
        )
    )
)
